  )
}

"use client"

import { useState, useEffect } from "react"
import { useRouter } from "next/navigation"
import { useSession } from "next-auth/react"
import Image from "next/image"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { Textarea } from "@/components/ui/textarea"
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select"
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card"
import { toast } from "@/hooks/use-toast"
import { Upload, X, Plus } from "lucide-react"

interface Category {
  id: number
  name: string
}

interface Material {
  id: number
  name: string
}

interface Size {
  id: number
  name: string
}

interface Color {
  id: number
  name: string
}

interface ProductFormData {
  name: string
  description: string
  price: string
  stock: string
  categoryId: string
  materialId: string
  sizeId: string
  colorId: string
  images: File[]
}

export default function CreateProductPage() {
  const router = useRouter()
  const { data: session, status } = useSession()
  const [isLoading, setIsLoading] = useState(false)
  const [categories, setCategories] = useState<Category[]>([])
  const [materials, setMaterials] = useState<Material[]>([])
  const [sizes, setSizes] = useState<Size[]>([])
  const [colors, setColors] = useState<Color[]>([])
  const [imagePreviewUrls, setImagePreviewUrls] = useState<string[]>([])

  const [formData, setFormData] = useState<ProductFormData>({
    name: "",
    description: "",
    price: "",
    stock: "",
    categoryId: "",
    materialId: "",
    sizeId: "",
    colorId: "",
    images: []
  })

  // Charger les données de référence
  useEffect(() => {
    const fetchReferenceData = async () => {
      try {
        const [categoriesRes, materialsRes, sizesRes, colorsRes] = await Promise.all([
          fetch('/api/products/categories'),
          fetch('/api/products/materials'),
          fetch('/api/products/sizes'),
          fetch('/api/products/colors')
        ])

        if (categoriesRes.ok) {
          const categoriesData = await categoriesRes.json()
          setCategories(categoriesData)
        }
        if (materialsRes.ok) {
          const materialsData = await materialsRes.json()
          setMaterials(materialsData)
        }
        if (sizesRes.ok) {
          const sizesData = await sizesRes.json()
          setSizes(sizesData)
        }
        if (colorsRes.ok) {
          const colorsData = await colorsRes.json()
          setColors(colorsData)
        }
      } catch (error) {
        console.error('Erreur lors du chargement des données:', error)
      }
    }

    fetchReferenceData()
  }, [])

  const handleInputChange = (field: keyof ProductFormData, value: string) => {
    console.log(`Mise à jour du champ ${field}:`, value)
    setFormData(prev => {
      const newData = {
        ...prev,
        [field]: value
      }
      console.log('FormData mis à jour:', newData)
      return newData
    })
  }

  const handleImageChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = Array.from(e.target.files || [])
    if (files.length > 0) {
      // Valider chaque fichier
      const validFiles: File[] = []
      const errors: string[] = []

      for (const file of files) {
        // Vérifier le type de fichier
        const allowedTypes = ['image/jpeg', 'image/jpg', 'image/png', 'image/webp']
        if (!allowedTypes.includes(file.type)) {
          errors.push(`${file.name}: Format non supporté`)
          continue
        }

        // Vérifier la taille (limite à 10MB pour le fichier original)
        const maxSize = 10 * 1024 * 1024 // 10MB
        if (file.size > maxSize) {
          errors.push(`${file.name}: Trop volumineux (max 10MB)`)
          continue
        }

        validFiles.push(file)
      }

      // Afficher les erreurs s'il y en a
      if (errors.length > 0) {
        toast({
          title: "Fichiers non valides",
          description: errors.join(', '),
          variant: "destructive"
        })
      }

      // Ajouter les fichiers valides
      if (validFiles.length > 0) {
        // Limiter à 5 images maximum
        const newImages = [...formData.images, ...validFiles].slice(0, 5)
        setFormData(prev => ({
          ...prev,
          images: newImages
        }))

        // Créer les URLs de prévisualisation
        const newPreviewUrls = validFiles.map(file => URL.createObjectURL(file))
        setImagePreviewUrls(prev => [...prev, ...newPreviewUrls].slice(0, 5))

        // Informer l'utilisateur de l'optimisation automatique
        if (validFiles.length > 0) {
          toast({
            title: "Images ajoutées",
            description: `${validFiles.length} image(s) ajoutée(s). Elles seront automatiquement optimisées (max 500KB, format WebP) lors de l'enregistrement.`,
          })
        }
      }
    }
  }

  const removeImage = (index: number) => {
    const newImages = formData.images.filter((_, i) => i !== index)
    const newPreviewUrls = imagePreviewUrls.filter((_, i) => i !== index)

    setFormData(prev => ({
      ...prev,
      images: newImages
    }))
    setImagePreviewUrls(newPreviewUrls)
  }

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()

    if (!session?.user?.id) {
      toast({
        title: "Erreur",
        description: "Vous devez être connecté pour créer un produit",
        variant: "destructive"
      })
      return
    }

    // Validation
    if (!formData.name.trim()) {
      toast({
        title: "Erreur",
        description: "Le nom du produit est obligatoire",
        variant: "destructive"
      })
      return
    }

    if (!formData.price || parseFloat(formData.price) <= 0) {
      toast({
        title: "Erreur",
        description: "Le prix doit être supérieur à 0",
        variant: "destructive"
      })
      return
    }

    if (!formData.categoryId || !formData.materialId || !formData.sizeId || !formData.colorId) {
      toast({
        title: "Erreur",
        description: "Veuillez sélectionner toutes les propriétés du produit",
        variant: "destructive"
      })
      return
    }

    if (formData.images.length === 0) {
      toast({
        title: "Erreur",
        description: "Veuillez ajouter au moins une image",
        variant: "destructive"
      })
      return
    }

    setIsLoading(true)

    try {
      // Créer FormData pour l'upload des images
      const submitFormData = new FormData()
      submitFormData.append('name', formData.name)
      submitFormData.append('description', formData.description)
      submitFormData.append('price', formData.price)
      submitFormData.append('stock', formData.stock || '0')
      submitFormData.append('categoryId', formData.categoryId)
      submitFormData.append('materialId', formData.materialId)
      submitFormData.append('sizeId', formData.sizeId)
      submitFormData.append('colorId', formData.colorId)

      // Ajouter les images
      formData.images.forEach((image, index) => {
        submitFormData.append(`images`, image)
      })

      const response = await fetch('/api/products/create', {
        method: 'POST',
        body: submitFormData
      })

      if (response.ok) {
        const result = await response.json()
        toast({
          title: "Succès",
          description: "Produit créé avec succès !",
        })
        router.push('/seller/catalogs')
      } else {
        const error = await response.json()
        throw new Error(error.message || 'Erreur lors de la création du produit')
      }
    } catch (error: any) {
      toast({
        title: "Erreur",
        description: error.message,
        variant: "destructive"
      })
    } finally {
      setIsLoading(false)
    }
  }

  if (status === "loading") {
    return <div className="flex justify-center items-center h-screen">Chargement...</div>
  }

  if (!session || session.user.role !== "SELLER") {
    router.push("/unauthorized")
    return null
  }

  return (
    <div className="container mx-auto px-4 py-8">
      <Card className="max-w-4xl mx-auto">
        <CardHeader>
          <CardTitle>Créer un nouveau produit</CardTitle>
          <CardDescription>
            Ajoutez un nouveau produit à votre catalogue
          </CardDescription>
        </CardHeader>
        <CardContent>
          <form onSubmit={handleSubmit} className="space-y-6">
            {/* Informations de base */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div className="space-y-2">
                <Label htmlFor="name">Nom du produit *</Label>
                <Input
                  id="name"
                  value={formData.name}
                  onChange={(e) => handleInputChange('name', e.target.value)}
                  placeholder="Ex: Robe élégante en soie"
                  required
                />
              </div>

              <div className="space-y-2">
                <Label htmlFor="price">Prix (€) *</Label>
                <Input
                  id="price"
                  type="number"
                  min="0"
                  step="0.01"
                  value={formData.price}
                  onChange={(e) => handleInputChange('price', e.target.value)}
                  placeholder="99.99"
                  required
                />
              </div>
            </div>

            <div className="space-y-2">
              <Label htmlFor="description">Description</Label>
              <Textarea
                id="description"
                value={formData.description}
                onChange={(e) => handleInputChange('description', e.target.value)}
                placeholder="Décrivez votre produit en détail..."
                rows={4}
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="stock">Stock disponible</Label>
              <Input
                id="stock"
                type="number"
                min="0"
                value={formData.stock}
                onChange={(e) => handleInputChange('stock', e.target.value)}
                placeholder="10"
              />
            </div>

            {/* Propriétés du produit */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div className="space-y-2">
                <Label htmlFor="category">Catégorie *</Label>
                <Select value={formData.categoryId} onValueChange={(value) => handleInputChange('categoryId', value)}>
                  <SelectTrigger>
                    <SelectValue placeholder="Sélectionner une catégorie" />
                  </SelectTrigger>
                  <SelectContent>
                    {categories.map((category) => (
                      <SelectItem key={category.id} value={category.id.toString()}>
                        {category.name}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>

              <div className="space-y-2">
                <Label htmlFor="material">Matériau *</Label>
                <Select value={formData.materialId} onValueChange={(value) => handleInputChange('materialId', value)}>
                  <SelectTrigger>
                    <SelectValue placeholder="Sélectionner un matériau" />
                  </SelectTrigger>
                  <SelectContent>
                    {materials.map((material) => (
                      <SelectItem key={material.id} value={material.id.toString()}>
                        {material.name}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>

              <div className="space-y-2">
                <Label htmlFor="size">Taille *</Label>
                <Select value={formData.sizeId} onValueChange={(value) => handleInputChange('sizeId', value)}>
                  <SelectTrigger>
                    <SelectValue placeholder="Sélectionner une taille" />
                  </SelectTrigger>
                  <SelectContent>
                    {sizes.map((size) => (
                      <SelectItem key={size.id} value={size.id.toString()}>
                        {size.name}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>

              <div className="space-y-2">
                <Label htmlFor="color">Couleur *</Label>
                <Select value={formData.colorId} onValueChange={(value) => handleInputChange('colorId', value)}>
                  <SelectTrigger>
                    <SelectValue placeholder="Sélectionner une couleur" />
                  </SelectTrigger>
                  <SelectContent>
                    {colors.map((color) => (
                      <SelectItem key={color.id} value={color.id.toString()}>
                        {color.name}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
            </div>

            {/* Images */}
            <div className="space-y-4">
              <Label>Images du produit * (Maximum 5 images)</Label>

              {/* Zone d'upload */}
              <div className="border-2 border-dashed border-gray-300 rounded-lg p-6 text-center">
                <input
                  type="file"
                  id="images"
                  accept="image/*"
                  multiple
                  onChange={handleImageChange}
                  className="hidden"
                />
                <label
                  htmlFor="images"
                  className="cursor-pointer flex flex-col items-center space-y-2"
                >
                  <Upload className="w-12 h-12 text-gray-400" />
                  <span className="text-sm text-gray-600">
                    Cliquez pour ajouter des images ou glissez-déposez
                  </span>
                  <span className="text-xs text-gray-400">
                    PNG, JPG, WEBP jusqu'à 10MB chacune
                  </span>
                </label>
              </div>

              {/* Prévisualisation des images */}
              {imagePreviewUrls.length > 0 && (
                <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-5 gap-4">
                  {imagePreviewUrls.map((url, index) => (
                    <div key={index} className="relative group">
                      <Image
                        src={url}
                        alt={`Preview ${index + 1}`}
                        width={200}
                        height={200}
                        className="w-full h-32 object-cover rounded-lg"
                      />
                      <button
                        type="button"
                        onClick={() => removeImage(index)}
                        className="absolute -top-2 -right-2 bg-red-500 text-white rounded-full p-1 opacity-0 group-hover:opacity-100 transition-opacity"
                      >
                        <X className="w-4 h-4" />
                      </button>
                    </div>
                  ))}
                </div>
              )}
            </div>

            {/* Boutons */}
            <div className="flex gap-4 pt-6">
              <Button
                type="button"
                variant="outline"
                onClick={() => router.back()}
                disabled={isLoading}
              >
                Annuler
              </Button>
              <Button type="submit" disabled={isLoading}>
                {isLoading ? "Création en cours..." : "Créer le produit"}
              </Button>
            </div>
          </form>
        </CardContent>
      </Card>
    </div>
  )
}

"use client"

import { useState, useEffect } from "react"
import { useRouter } from "next/navigation"
import { useSession } from "next-auth/react"
import Image from "next/image"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { Textarea } from "@/components/ui/textarea"
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select"
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card"
import { toast } from "@/hooks/use-toast"
import { Upload, X, Plus } from "lucide-react"

interface Category {
  id: number
  name: string
}

interface Material {
  id: number
  name: string
}

interface Size {
  id: number
  name: string
}

interface Color {
  id: number
  name: string
}

interface ProductFormData {
  name: string
  description: string
  price: string
  stock: string
  categoryId: string
  materialId: string
  sizeId: string
  colorId: string
  images: File[]
}

export default function CreateProductPage() {
  const router = useRouter()
  const { data: session, status } = useSession()
  const [isLoading, setIsLoading] = useState(false)
  const [categories, setCategories] = useState<Category[]>([])
  const [materials, setMaterials] = useState<Material[]>([])
  const [sizes, setSizes] = useState<Size[]>([])
  const [colors, setColors] = useState<Color[]>([])
  const [imagePreviewUrls, setImagePreviewUrls] = useState<string[]>([])

  const [formData, setFormData] = useState<ProductFormData>({
    name: "",
    description: "",
    price: "",
    stock: "",
    categoryId: "",
    materialId: "",
    sizeId: "",
    colorId: "",
    images: []
  })

  // Charger les données de référence
  useEffect(() => {
    const fetchReferenceData = async () => {
      try {
        const [categoriesRes, materialsRes, sizesRes, colorsRes] = await Promise.all([
          fetch('/api/products/categories'),
          fetch('/api/products/materials'),
          fetch('/api/products/sizes'),
          fetch('/api/products/colors')
        ])

        if (categoriesRes.ok) {
          const categoriesData = await categoriesRes.json()
          setCategories(categoriesData)
        }
        if (materialsRes.ok) {
          const materialsData = await materialsRes.json()
          setMaterials(materialsData)
        }
        if (sizesRes.ok) {
          const sizesData = await sizesRes.json()
          setSizes(sizesData)
        }
        if (colorsRes.ok) {
          const colorsData = await colorsRes.json()
          setColors(colorsData)
        }
      } catch (error) {
        console.error('Erreur lors du chargement des données:', error)
      }
    }

    fetchReferenceData()
  }, [])

  const handleInputChange = (field: keyof ProductFormData, value: string) => {
    console.log(`Mise à jour du champ ${field}:`, value)
    setFormData(prev => {
      const newData = {
        ...prev,
        [field]: value
      }
      console.log('FormData mis à jour:', newData)
      return newData
    })
  }

  const handleImageChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = Array.from(e.target.files || [])
    if (files.length > 0) {
      // Valider chaque fichier
      const validFiles: File[] = []
      const errors: string[] = []

      for (const file of files) {
        // Vérifier le type de fichier
        const allowedTypes = ['image/jpeg', 'image/jpg', 'image/png', 'image/webp']
        if (!allowedTypes.includes(file.type)) {
          errors.push(`${file.name}: Format non supporté`)
          continue
        }

        // Vérifier la taille (limite à 10MB pour le fichier original)
        const maxSize = 10 * 1024 * 1024 // 10MB
        if (file.size > maxSize) {
          errors.push(`${file.name}: Trop volumineux (max 10MB)`)
          continue
        }

        validFiles.push(file)
      }

      // Afficher les erreurs s'il y en a
      if (errors.length > 0) {
        toast({
          title: "Fichiers non valides",
          description: errors.join(', '),
          variant: "destructive"
        })
      }

      // Ajouter les fichiers valides
      if (validFiles.length > 0) {
        // Limiter à 5 images maximum
        const newImages = [...formData.images, ...validFiles].slice(0, 5)
        setFormData(prev => ({
          ...prev,
          images: newImages
        }))

        // Créer les URLs de prévisualisation
        const newPreviewUrls = validFiles.map(file => URL.createObjectURL(file))
        setImagePreviewUrls(prev => [...prev, ...newPreviewUrls].slice(0, 5))

        // Informer l'utilisateur de l'optimisation automatique
        if (validFiles.length > 0) {
          toast({
            title: "Images ajoutées",
            description: `${validFiles.length} image(s) ajoutée(s). Elles seront automatiquement optimisées (max 500KB, format WebP) lors de l'enregistrement.`,
          })
        }
      }
    }
  }

  const removeImage = (index: number) => {
    const newImages = formData.images.filter((_, i) => i !== index)
    const newPreviewUrls = imagePreviewUrls.filter((_, i) => i !== index)

    setFormData(prev => ({
      ...prev,
      images: newImages
    }))
    setImagePreviewUrls(newPreviewUrls)
  }

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()

    if (!session?.user?.id) {
      toast({
        title: "Erreur",
        description: "Vous devez être connecté pour créer un produit",
        variant: "destructive"
      })
      return
    }

    // Validation
    if (!formData.name.trim()) {
      toast({
        title: "Erreur",
        description: "Le nom du produit est obligatoire",
        variant: "destructive"
      })
      return
    }

    if (!formData.price || parseFloat(formData.price) <= 0) {
      toast({
        title: "Erreur",
        description: "Le prix doit être supérieur à 0",
        variant: "destructive"
      })
      return
    }

    if (!formData.categoryId || !formData.materialId || !formData.sizeId || !formData.colorId) {
      toast({
        title: "Erreur",
        description: "Veuillez sélectionner toutes les propriétés du produit",
        variant: "destructive"
      })
      return
    }

    if (formData.images.length === 0) {
      toast({
        title: "Erreur",
        description: "Veuillez ajouter au moins une image",
        variant: "destructive"
      })
      return
    }

    setIsLoading(true)

    try {
      // Créer FormData pour l'upload des images
      const submitFormData = new FormData()
      submitFormData.append('name', formData.name)
      submitFormData.append('description', formData.description)
      submitFormData.append('price', formData.price)
      submitFormData.append('stock', formData.stock || '0')
      submitFormData.append('categoryId', formData.categoryId)
      submitFormData.append('materialId', formData.materialId)
      submitFormData.append('sizeId', formData.sizeId)
      submitFormData.append('colorId', formData.colorId)

      // Ajouter les images
      formData.images.forEach((image, index) => {
        submitFormData.append(`images`, image)
      })

      const response = await fetch('/api/products/create', {
        method: 'POST',
        body: submitFormData
      })

      if (response.ok) {
        const result = await response.json()
        toast({
          title: "Succès",
          description: "Produit créé avec succès !",
        })
        router.push('/seller/catalogs')
      } else {
        const error = await response.json()
        throw new Error(error.message || 'Erreur lors de la création du produit')
      }
    } catch (error: any) {
      toast({
        title: "Erreur",
        description: error.message,
        variant: "destructive"
      })
    } finally {
      setIsLoading(false)
    }
  }

  if (status === "loading") {
    return <div className="flex justify-center items-center h-screen">Chargement...</div>
  }

  if (!session || session.user.role !== "SELLER") {
    router.push("/unauthorized")
    return null
  }

  return (
    <div className="container mx-auto px-4 py-8">
      <Card className="max-w-4xl mx-auto">
        <CardHeader>
          <CardTitle>Créer un nouveau produit</CardTitle>
          <CardDescription>
            Ajoutez un nouveau produit à votre catalogue
          </CardDescription>
        </CardHeader>
        <CardContent>
          <form onSubmit={handleSubmit} className="space-y-6">
            {/* Informations de base */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div className="space-y-2">
                <Label htmlFor="name">Nom du produit *</Label>
                <Input
                  id="name"
                  value={formData.name}
                  onChange={(e) => handleInputChange('name', e.target.value)}
                  placeholder="Ex: Robe élégante en soie"
                  required
                />
              </div>

              <div className="space-y-2">
                <Label htmlFor="price">Prix (€) *</Label>
                <Input
                  id="price"
                  type="number"
                  min="0"
                  step="0.01"
                  value={formData.price}
                  onChange={(e) => handleInputChange('price', e.target.value)}
                  placeholder="99.99"
                  required
                />
              </div>
            </div>

            <div className="space-y-2">
              <Label htmlFor="description">Description</Label>
              <Textarea
                id="description"
                value={formData.description}
                onChange={(e) => handleInputChange('description', e.target.value)}
                placeholder="Décrivez votre produit en détail..."
                rows={4}
              />
            </div>

            <div className="space-y-2">
              <Label htmlFor="stock">Stock disponible</Label>
              <Input
                id="stock"
                type="number"
                min="0"
                value={formData.stock}
                onChange={(e) => handleInputChange('stock', e.target.value)}
                placeholder="10"
              />
            </div>

            {/* Propriétés du produit */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div className="space-y-2">
                <Label htmlFor="category">Catégorie *</Label>
                <Select value={formData.categoryId} onValueChange={(value) => handleInputChange('categoryId', value)}>
                  <SelectTrigger>
                    <SelectValue placeholder="Sélectionner une catégorie" />
                  </SelectTrigger>
                  <SelectContent>
                    {categories.map((category) => (
                      <SelectItem key={category.id} value={category.id.toString()}>
                        {category.name}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>

              <div className="space-y-2">
                <Label htmlFor="material">Matériau *</Label>
                <Select value={formData.materialId} onValueChange={(value) => handleInputChange('materialId', value)}>
                  <SelectTrigger>
                    <SelectValue placeholder="Sélectionner un matériau" />
                  </SelectTrigger>
                  <SelectContent>
                    {materials.map((material) => (
                      <SelectItem key={material.id} value={material.id.toString()}>
                        {material.name}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>

              <div className="space-y-2">
                <Label htmlFor="size">Taille *</Label>
                <Select value={formData.sizeId} onValueChange={(value) => handleInputChange('sizeId', value)}>
                  <SelectTrigger>
                    <SelectValue placeholder="Sélectionner une taille" />
                  </SelectTrigger>
                  <SelectContent>
                    {sizes.map((size) => (
                      <SelectItem key={size.id} value={size.id.toString()}>
                        {size.name}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>

              <div className="space-y-2">
                <Label htmlFor="color">Couleur *</Label>
                <Select value={formData.colorId} onValueChange={(value) => handleInputChange('colorId', value)}>
                  <SelectTrigger>
                    <SelectValue placeholder="Sélectionner une couleur" />
                  </SelectTrigger>
                  <SelectContent>
                    {colors.map((color) => (
                      <SelectItem key={color.id} value={color.id.toString()}>
                        {color.name}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
            </div>

            {/* Images */}
            <div className="space-y-4">
              <Label>Images du produit * (Maximum 5 images)</Label>

              {/* Zone d'upload */}
              <div className="border-2 border-dashed border-gray-300 rounded-lg p-6 text-center">
                <input
                  type="file"
                  id="images"
                  accept="image/*"
                  multiple
                  onChange={handleImageChange}
                  className="hidden"
                />
                <label
                  htmlFor="images"
                  className="cursor-pointer flex flex-col items-center space-y-2"
                >
                  <Upload className="w-12 h-12 text-gray-400" />
                  <span className="text-sm text-gray-600">
                    Cliquez pour ajouter des images ou glissez-déposez
                  </span>
                  <span className="text-xs text-gray-400">
                    PNG, JPG, WEBP jusqu'à 10MB chacune
                  </span>
                </label>
              </div>

              {/* Prévisualisation des images */}
              {imagePreviewUrls.length > 0 && (
                <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-5 gap-4">
                  {imagePreviewUrls.map((url, index) => (
                    <div key={index} className="relative group">
                      <Image
                        src={url}
                        alt={`Preview ${index + 1}`}
                        width={200}
                        height={200}
                        className="w-full h-32 object-cover rounded-lg"
                      />
                      <button
                        type="button"
                        onClick={() => removeImage(index)}
                        className="absolute -top-2 -right-2 bg-red-500 text-white rounded-full p-1 opacity-0 group-hover:opacity-100 transition-opacity"
                      >
                        <X className="w-4 h-4" />
                      </button>
                    </div>
                  ))}
                </div>
              )}
            </div>

            {/* Boutons */}
            <div className="flex gap-4 pt-6">
              <Button
                type="button"
                variant="outline"
                onClick={() => router.back()}
                disabled={isLoading}
              >
                Annuler
              </Button>
              <Button type="submit" disabled={isLoading}>
                {isLoading ? "Création en cours..." : "Créer le produit"}
              </Button>
            </div>
          </form>
        </CardContent>
      </Card>
    </div>
  )
}

"use client"

import { useRequireRole } from "@/hooks/use-auth"
import { useState, useEffect } from "react"
import ProjectModal from "@/components/project-modal"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Textarea } from "@/components/ui/textarea"
import { Label } from "@/components/ui/label"
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog"
import {
  FolderOpen,
  Search,
  RefreshCw,
  Eye,
  Send,
  User,
  MapPin,
  Calendar,
  MessageSquare,
  Euro,
  Clock,
  Filter
} from "lucide-react"
import { useToast } from "@/hooks/use-toast"

export default function SellerProjects() {
  const { user, isLoading, hasCorrectRole } = useRequireRole("SELLER")
  const [projects, setProjects] = useState([])
  const [loading, setLoading] = useState(true)
  const [selectedFilter, setSelectedFilter] = useState("all")
  const [searchTerm, setSearchTerm] = useState("")
  const [selectedProject, setSelectedProject] = useState<any>(null)
  const [modalOpen, setModalOpen] = useState(false)
  const [proposalModalOpen, setProposalModalOpen] = useState(false)
  const [submittingProposal, setSubmittingProposal] = useState(false)
  const { toast } = useToast()

  // Form states for new proposal
  const [newProposal, setNewProposal] = useState({
    price: "",
    message: "",
    deliveryTime: "",
  })

  useEffect(() => {
    if (hasCorrectRole) {
      fetchAvailableProjects()
    }
  }, [hasCorrectRole])

  const handleViewDetails = (project: any) => {
    setSelectedProject(project)
    setModalOpen(true)
  }

  const handleOpenProposalModal = (project: any) => {
    setSelectedProject(project)
    setProposalModalOpen(true)
  }

  const fetchAvailableProjects = async () => {
    try {
      setLoading(true)
      const response = await fetch("/api/projects/available")
      if (response.ok) {
        const data = await response.json()
        setProjects(data)
      } else {
        console.error("Erreur lors du chargement des projets")
      }
    } catch (error) {
      console.error("Erreur lors du chargement des projets :", error)
    } finally {
      setLoading(false)
    }
  }

  const handleSubmitProposal = async (e: React.FormEvent) => {
    e.preventDefault()
    setSubmittingProposal(true)

    try {
      const response = await fetch(`/api/seller/projects/${selectedProject.id}/proposal`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          ...newProposal,
          price: parseFloat(newProposal.price),
        }),
      })

      if (response.ok) {
        toast({
          title: "Offre envoyée !",
          description: "Votre proposition a été envoyée au client avec succès.",
        })
        setProposalModalOpen(false)
        setNewProposal({ price: "", message: "", deliveryTime: "" })
        fetchAvailableProjects() // Refresh projects
      } else {
        throw new Error("Erreur lors de l'envoi de l'offre")
      }
    } catch (error) {
      toast({
        title: "Erreur",
        description: "Impossible d'envoyer l'offre. Veuillez réessayer.",
        variant: "destructive",
      })
    } finally {
      setSubmittingProposal(false)
    }
  }

  if (isLoading) {
    return (
        <div className="flex items-center justify-center min-h-screen">
          <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-teal-600"></div>
        </div>
    )
  }

  if (!hasCorrectRole) {
    return null
  }

  const filteredProjects = projects.filter((project: any) => {
    const matchesFilter =
        selectedFilter === "all" || project.category?.toLowerCase() === selectedFilter
    const matchesSearch =
        project.title?.toLowerCase().includes(searchTerm.toLowerCase()) ||
        project.description?.toLowerCase().includes(searchTerm.toLowerCase())
    return matchesFilter && matchesSearch
  })

  const getStatusBadge = (status: string) => {
    const statusStyles = {
      open: "bg-green-100 text-green-800",
      in_progress: "bg-blue-100 text-blue-800",
      completed: "bg-gray-100 text-gray-800",
      closed: "bg-red-100 text-red-800",
    }
    return statusStyles[status as keyof typeof statusStyles] || statusStyles.open
  }

  const categories = ["all", "suits", "dresses", "alterations"]

  return (
    <div className="min-h-screen bg-gradient-to-br from-gray-50 to-white">
      {/* Hero Section */}
      <div className="bg-gradient-to-r from-teal-600 to-teal-700 text-white py-12">
        <div className="container mx-auto px-4">
          <div className="flex items-center gap-6">
            <div className="bg-white/20 p-4 rounded-full">
              <FolderOpen className="h-12 w-12" />
            </div>
            <div>
              <h1 className="text-3xl font-bold mb-2">Projets Disponibles</h1>
              <p className="text-teal-100 text-lg">
                Découvrez les projets proposés par les clients et déposez vos offres
              </p>
            </div>
          </div>
        </div>
      </div>

      <div className="container mx-auto px-4 py-8">
        {/* Filters & Search */}
        <div className="bg-white rounded-2xl shadow-sm border border-gray-100 p-6 mb-8 -mt-6 relative z-10">
          <div className="flex flex-col lg:flex-row gap-6 items-start lg:items-center justify-between">
            {/* Categories Filter */}
            <div className="flex items-center gap-4">
              <Filter className="h-5 w-5 text-teal-600" />
              <div className="flex flex-wrap gap-2">
                {categories.map((cat) => (
                  <button
                    key={cat}
                    onClick={() => setSelectedFilter(cat)}
                    className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors ${
                      selectedFilter === cat
                        ? "bg-teal-600 text-white shadow-sm"
                        : "bg-gray-100 text-gray-700 hover:bg-gray-200"
                    }`}
                  >
                    {cat === "all" ? "Tous les projets" : cat.charAt(0).toUpperCase() + cat.slice(1)}
                  </button>
                ))}
              </div>
            </div>

            {/* Search & Refresh */}
            <div className="flex gap-3">
              <div className="relative">
                <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 h-4 w-4 text-gray-400" />
                <Input
                  type="search"
                  placeholder="Rechercher des projets..."
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                  className="pl-10 w-64 h-10 rounded-lg border-gray-200 focus:border-teal-500 focus:ring-teal-500"
                />
              </div>
              <Button
                onClick={fetchAvailableProjects}
                variant="outline"
                size="sm"
                className="h-10"
              >
                <RefreshCw className="h-4 w-4 mr-2" />
                Actualiser
              </Button>
            </div>
          </div>
        </div>

        {/* Projects List */}
        {loading ? (
          <div className="text-center py-12">
            <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-teal-600 mx-auto mb-4"></div>
            <p className="text-gray-600">Chargement des projets...</p>
          </div>
        ) : filteredProjects.length > 0 ? (
          <div className="space-y-6">
            {filteredProjects.map((project: any) => (
              <div
                key={project.id}
                className="bg-white rounded-2xl shadow-sm border border-gray-100 p-8 hover:shadow-md transition-shadow relative"
              >
                {/* Actions - positioned absolutely */}
                <div className="absolute top-6 right-6 flex gap-3">
                  <Button
                    onClick={() => handleViewDetails(project)}
                    variant="outline"
                    size="sm"
                  >
                    <Eye className="h-4 w-4 mr-2" />
                    Voir détails
                  </Button>
                  <Button
                    onClick={() => handleOpenProposalModal(project)}
                    size="sm"
                    className="bg-teal-600 hover:bg-teal-700"
                  >
                    <Send className="h-4 w-4 mr-2" />
                    Déposer une offre
                  </Button>
                </div>

                <div className="pr-80"> {/* Add right padding to avoid button overlap */}
                  {/* Project Content */}
                  <div className="flex-1">
                    <div className="flex items-start justify-between mb-4">
                      <div className="flex items-center gap-3">
                        <h3 className="text-2xl font-bold text-gray-900">{project.title}</h3>
                        <span className={`px-3 py-1 rounded-full text-sm font-medium ${getStatusBadge(project.status)}`}>
                          {project.status === "open" ? "Ouvert" : project.status}
                        </span>
                      </div>
                      {project.budget && (
                        <div className="text-2xl font-bold text-teal-600">{project.budget}</div>
                      )}
                    </div>

                    <p className="text-gray-600 mb-6 leading-relaxed">
                      {project.description?.length > 30
                        ? `${project.description.substring(0, 30)}...`
                        : project.description}
                    </p>

                    {/* Project Meta */}
                    <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-6">
                      <div className="flex items-center gap-2 text-sm text-gray-600">
                        <User className="h-4 w-4 text-teal-600" />
                        <span>{project.client?.name || "Client anonyme"}</span>
                      </div>
                      {project.location && (
                        <div className="flex items-center gap-2 text-sm text-gray-600">
                          <MapPin className="h-4 w-4 text-teal-600" />
                          <span>{project.location}</span>
                        </div>
                      )}
                      {project.deadline && (
                        <div className="flex items-center gap-2 text-sm text-gray-600">
                          <Calendar className="h-4 w-4 text-teal-600" />
                          <span>{new Date(project.deadline).toLocaleDateString("fr-FR")}</span>
                        </div>
                      )}
                      <div className="flex items-center gap-2 text-sm text-gray-600">
                        <MessageSquare className="h-4 w-4 text-teal-600" />
                        <span>{project._count?.proposals || 0} offre(s)</span>
                      </div>
                    </div>

                    {/* Category & Date */}
                    <div className="flex items-center justify-between">
                      <div className="flex items-center gap-3">
                        {project.category && (
                          <span className="bg-teal-50 text-teal-700 px-3 py-1 rounded-lg text-sm font-medium">
                            {project.category}
                          </span>
                        )}
                        <span className="text-sm text-gray-500 flex items-center gap-1">
                          <Clock className="h-4 w-4" />
                          Publié le {new Date(project.createdAt).toLocaleDateString("fr-FR")}
                        </span>
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            ))}
          </div>
        ) : (
          <div className="text-center py-16">
            <div className="bg-white rounded-2xl shadow-sm border border-gray-100 p-12 max-w-md mx-auto">
              <FolderOpen className="h-16 w-16 text-gray-300 mx-auto mb-6" />
              <h3 className="text-xl font-semibold text-gray-900 mb-3">Aucun projet disponible</h3>
              <p className="text-gray-600 mb-6">
                {searchTerm || selectedFilter !== "all"
                  ? "Aucun projet ne correspond à vos critères de recherche."
                  : "Aucun projet n'a été publié par les clients pour le moment."}
              </p>
              {(searchTerm || selectedFilter !== "all") && (
                <Button
                  onClick={() => {
                    setSearchTerm("")
                    setSelectedFilter("all")
                  }}
                  className="bg-teal-600 hover:bg-teal-700"
                >
                  Voir tous les projets
                </Button>
              )}
            </div>
          </div>
        )}
      </div>

      {/* Project Details Modal */}
      <ProjectModal
        open={modalOpen}
        onClose={() => setModalOpen(false)}
        project={selectedProject}
      />

      {/* Submit Proposal Modal */}
      <Dialog open={proposalModalOpen} onOpenChange={setProposalModalOpen}>
        <DialogContent className="max-w-2xl">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-3 text-2xl">
              <Send className="h-6 w-6 text-teal-600" />
              Déposer une offre
            </DialogTitle>
            <p className="text-gray-600">
              Projet : <strong>{selectedProject?.title}</strong>
            </p>
          </DialogHeader>

          <form onSubmit={handleSubmitProposal} className="space-y-6 pt-4">
            <div>
              <Label htmlFor="price" className="text-sm font-medium text-gray-700 flex items-center gap-2">
                <Euro className="h-4 w-4 text-teal-600" />
                Prix proposé (€) *
              </Label>
              <Input
                id="price"
                type="number"
                step="0.01"
                value={newProposal.price}
                onChange={(e) => setNewProposal(prev => ({ ...prev, price: e.target.value }))}
                placeholder="Ex: 250.00"
                className="mt-2 h-12 rounded-lg border-gray-200 focus:border-teal-500 focus:ring-teal-500"
                required
              />
            </div>

            <div>
              <Label htmlFor="deliveryTime" className="text-sm font-medium text-gray-700 flex items-center gap-2">
                <Clock className="h-4 w-4 text-teal-600" />
                Délai de livraison
              </Label>
              <Input
                id="deliveryTime"
                value={newProposal.deliveryTime}
                onChange={(e) => setNewProposal(prev => ({ ...prev, deliveryTime: e.target.value }))}
                placeholder="Ex: 2 semaines, 10 jours..."
                className="mt-2 h-12 rounded-lg border-gray-200 focus:border-teal-500 focus:ring-teal-500"
              />
            </div>

            <div>
              <Label htmlFor="message" className="text-sm font-medium text-gray-700 flex items-center gap-2">
                <MessageSquare className="h-4 w-4 text-teal-600" />
                Message pour le client *
              </Label>
              <Textarea
                id="message"
                value={newProposal.message}
                onChange={(e) => setNewProposal(prev => ({ ...prev, message: e.target.value }))}
                placeholder="Présentez-vous, expliquez votre approche, votre expérience dans ce domaine..."
                rows={6}
                className="mt-2 rounded-lg border-gray-200 focus:border-teal-500 focus:ring-teal-500 resize-none"
                required
              />
            </div>

            <div className="flex gap-3 pt-4">
              <Button
                type="button"
                variant="outline"
                onClick={() => setProposalModalOpen(false)}
                className="flex-1"
                disabled={submittingProposal}
              >
                Annuler
              </Button>
              <Button
                type="submit"
                className="flex-1 bg-teal-600 hover:bg-teal-700"
                disabled={submittingProposal}
              >
                {submittingProposal ? (
                  <div className="flex items-center gap-2">
                    <div className="animate-spin rounded-full h-4 w-4 border-b-2 border-white"></div>
                    Envoi en cours...
                  </div>
                ) : (
                  <>
                    <Send className="h-4 w-4 mr-2" />
                    Envoyer l'offre
                  </>
                )}
              </Button>
            </div>
          </form>
        </DialogContent>
      </Dialog>
    </div>
  )
}

"use client"

import { useRequireRole } from "@/hooks/use-auth"
import { useState, useEffect } from "react"
import ProjectModal from "@/components/project-modal"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Textarea } from "@/components/ui/textarea"
import { Label } from "@/components/ui/label"
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog"
import {
  FolderOpen,
  Search,
  RefreshCw,
  Eye,
  Send,
  User,
  MapPin,
  Calendar,
  MessageSquare,
  Euro,
  Clock,
  Filter
} from "lucide-react"
import { useToast } from "@/hooks/use-toast"

export default function SellerProjects() {
  const { user, isLoading, hasCorrectRole } = useRequireRole("SELLER")
  const [projects, setProjects] = useState([])
  const [loading, setLoading] = useState(true)
  const [selectedFilter, setSelectedFilter] = useState("all")
  const [searchTerm, setSearchTerm] = useState("")
  const [selectedProject, setSelectedProject] = useState<any>(null)
  const [modalOpen, setModalOpen] = useState(false)
  const [proposalModalOpen, setProposalModalOpen] = useState(false)
  const [submittingProposal, setSubmittingProposal] = useState(false)
  const { toast } = useToast()

  // Form states for new proposal
  const [newProposal, setNewProposal] = useState({
    price: "",
    message: "",
    deliveryTime: "",
  })

  useEffect(() => {
    if (hasCorrectRole) {
      fetchAvailableProjects()
    }
  }, [hasCorrectRole])

  const handleViewDetails = (project: any) => {
    setSelectedProject(project)
    setModalOpen(true)
  }

  const handleOpenProposalModal = (project: any) => {
    setSelectedProject(project)
    setProposalModalOpen(true)
  }

  const fetchAvailableProjects = async () => {
    try {
      setLoading(true)
      const response = await fetch("/api/projects/available")
      if (response.ok) {
        const data = await response.json()
        setProjects(data)
      } else {
        console.error("Erreur lors du chargement des projets")
      }
    } catch (error) {
      console.error("Erreur lors du chargement des projets :", error)
    } finally {
      setLoading(false)
    }
  }

  const handleSubmitProposal = async (e: React.FormEvent) => {
    e.preventDefault()
    setSubmittingProposal(true)

    try {
      const response = await fetch(`/api/seller/projects/${selectedProject.id}/proposal`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          ...newProposal,
          price: parseFloat(newProposal.price),
        }),
      })

      if (response.ok) {
        toast({
          title: "Offre envoyée !",
          description: "Votre proposition a été envoyée au client avec succès.",
        })
        setProposalModalOpen(false)
        setNewProposal({ price: "", message: "", deliveryTime: "" })
        fetchAvailableProjects() // Refresh projects
      } else {
        throw new Error("Erreur lors de l'envoi de l'offre")
      }
    } catch (error) {
      toast({
        title: "Erreur",
        description: "Impossible d'envoyer l'offre. Veuillez réessayer.",
        variant: "destructive",
      })
    } finally {
      setSubmittingProposal(false)
    }
  }

  if (isLoading) {
    return (
        <div className="flex items-center justify-center min-h-screen">
          <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-teal-600"></div>
        </div>
    )
  }

  if (!hasCorrectRole) {
    return null
  }

  const filteredProjects = projects.filter((project: any) => {
    const matchesFilter =
        selectedFilter === "all" || project.category?.toLowerCase() === selectedFilter
    const matchesSearch =
        project.title?.toLowerCase().includes(searchTerm.toLowerCase()) ||
        project.description?.toLowerCase().includes(searchTerm.toLowerCase())
    return matchesFilter && matchesSearch
  })

  const getStatusBadge = (status: string) => {
    const statusStyles = {
      open: "bg-green-100 text-green-800",
      in_progress: "bg-blue-100 text-blue-800",
      completed: "bg-gray-100 text-gray-800",
      closed: "bg-red-100 text-red-800",
    }
    return statusStyles[status as keyof typeof statusStyles] || statusStyles.open
  }

  const categories = ["all", "suits", "dresses", "alterations"]

  return (
    <div className="min-h-screen bg-gradient-to-br from-gray-50 to-white">
      {/* Hero Section */}
      <div className="bg-gradient-to-r from-teal-600 to-teal-700 text-white py-12">
        <div className="container mx-auto px-4">
          <div className="flex items-center gap-6">
            <div className="bg-white/20 p-4 rounded-full">
              <FolderOpen className="h-12 w-12" />
            </div>
            <div>
              <h1 className="text-3xl font-bold mb-2">Projets Disponibles</h1>
              <p className="text-teal-100 text-lg">
                Découvrez les projets proposés par les clients et déposez vos offres
              </p>
            </div>
          </div>
        </div>
      </div>

      <div className="container mx-auto px-4 py-8">
        {/* Filters & Search */}
        <div className="bg-white rounded-2xl shadow-sm border border-gray-100 p-6 mb-8 -mt-6 relative z-10">
          <div className="flex flex-col lg:flex-row gap-6 items-start lg:items-center justify-between">
            {/* Categories Filter */}
            <div className="flex items-center gap-4">
              <Filter className="h-5 w-5 text-teal-600" />
              <div className="flex flex-wrap gap-2">
                {categories.map((cat) => (
                  <button
                    key={cat}
                    onClick={() => setSelectedFilter(cat)}
                    className={`px-4 py-2 rounded-lg text-sm font-medium transition-colors ${
                      selectedFilter === cat
                        ? "bg-teal-600 text-white shadow-sm"
                        : "bg-gray-100 text-gray-700 hover:bg-gray-200"
                    }`}
                  >
                    {cat === "all" ? "Tous les projets" : cat.charAt(0).toUpperCase() + cat.slice(1)}
                  </button>
                ))}
              </div>
            </div>

            {/* Search & Refresh */}
            <div className="flex gap-3">
              <div className="relative">
                <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 h-4 w-4 text-gray-400" />
                <Input
                  type="search"
                  placeholder="Rechercher des projets..."
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                  className="pl-10 w-64 h-10 rounded-lg border-gray-200 focus:border-teal-500 focus:ring-teal-500"
                />
              </div>
              <Button
                onClick={fetchAvailableProjects}
                variant="outline"
                size="sm"
                className="h-10"
              >
                <RefreshCw className="h-4 w-4 mr-2" />
                Actualiser
              </Button>
            </div>
          </div>
        </div>

        {/* Projects List */}
        {loading ? (
          <div className="text-center py-12">
            <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-teal-600 mx-auto mb-4"></div>
            <p className="text-gray-600">Chargement des projets...</p>
          </div>
        ) : filteredProjects.length > 0 ? (
          <div className="space-y-6">
            {filteredProjects.map((project: any) => (
              <div
                key={project.id}
                className="bg-white rounded-2xl shadow-sm border border-gray-100 p-8 hover:shadow-md transition-shadow relative"
              >
                {/* Actions - positioned absolutely */}
                <div className="absolute top-6 right-6 flex flex-col gap-3 w-48">
                  <Button
                    onClick={() => handleViewDetails(project)}
                    variant="outline"
                    className="w-full"
                  >
                    <Eye className="h-4 w-4 mr-2" />
                    Voir détails
                  </Button>
                  <Button
                    onClick={() => handleOpenProposalModal(project)}
                    className="w-full bg-teal-600 hover:bg-teal-700"
                  >
                    <Send className="h-4 w-4 mr-2" />
                    Déposer une offre
                  </Button>
                </div>

                <div className="pr-80"> {/* Add right padding to avoid button overlap */}
                  {/* Project Content */}
                  <div className="flex-1">
                    <div className="flex items-start justify-between mb-4">
                      <div className="flex items-center gap-3">
                        <h3 className="text-2xl font-bold text-gray-900">{project.title}</h3>
                        <span className={`px-3 py-1 rounded-full text-sm font-medium ${getStatusBadge(project.status)}`}>
                          {project.status === "open" ? "Ouvert" : project.status}
                        </span>
                      </div>
                      {project.budget && (
                        <div className="text-2xl font-bold text-teal-600">{project.budget}</div>
                      )}
                    </div>

                    <p className="text-gray-600 mb-6 leading-relaxed">
                      {project.description?.length > 30
                        ? `${project.description.substring(0, 30)}...`
                        : project.description}
                    </p>

                    {/* Project Meta */}
                    <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-6">
                      <div className="flex items-center gap-2 text-sm text-gray-600">
                        <User className="h-4 w-4 text-teal-600" />
                        <span>{project.client?.name || "Client anonyme"}</span>
                      </div>
                      {project.location && (
                        <div className="flex items-center gap-2 text-sm text-gray-600">
                          <MapPin className="h-4 w-4 text-teal-600" />
                          <span>{project.location}</span>
                        </div>
                      )}
                      {project.deadline && (
                        <div className="flex items-center gap-2 text-sm text-gray-600">
                          <Calendar className="h-4 w-4 text-teal-600" />
                          <span>{new Date(project.deadline).toLocaleDateString("fr-FR")}</span>
                        </div>
                      )}
                      <div className="flex items-center gap-2 text-sm text-gray-600">
                        <MessageSquare className="h-4 w-4 text-teal-600" />
                        <span>{project._count?.proposals || 0} offre(s)</span>
                      </div>
                    </div>

                    {/* Category & Date */}
                    <div className="flex items-center justify-between">
                      <div className="flex items-center gap-3">
                        {project.category && (
                          <span className="bg-teal-50 text-teal-700 px-3 py-1 rounded-lg text-sm font-medium">
                            {project.category}
                          </span>
                        )}
                        <span className="text-sm text-gray-500 flex items-center gap-1">
                          <Clock className="h-4 w-4" />
                          Publié le {new Date(project.createdAt).toLocaleDateString("fr-FR")}
                        </span>
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            ))}
          </div>
        ) : (
          <div className="text-center py-16">
            <div className="bg-white rounded-2xl shadow-sm border border-gray-100 p-12 max-w-md mx-auto">
              <FolderOpen className="h-16 w-16 text-gray-300 mx-auto mb-6" />
              <h3 className="text-xl font-semibold text-gray-900 mb-3">Aucun projet disponible</h3>
              <p className="text-gray-600 mb-6">
                {searchTerm || selectedFilter !== "all"
                  ? "Aucun projet ne correspond à vos critères de recherche."
                  : "Aucun projet n'a été publié par les clients pour le moment."}
              </p>
              {(searchTerm || selectedFilter !== "all") && (
                <Button
                  onClick={() => {
                    setSearchTerm("")
                    setSelectedFilter("all")
                  }}
                  className="bg-teal-600 hover:bg-teal-700"
                >
                  Voir tous les projets
                </Button>
              )}
            </div>
          </div>
        )}
      </div>

      {/* Project Details Modal */}
      <ProjectModal
        open={modalOpen}
        onClose={() => setModalOpen(false)}
        project={selectedProject}
      />

      {/* Submit Proposal Modal */}
      <Dialog open={proposalModalOpen} onOpenChange={setProposalModalOpen}>
        <DialogContent className="max-w-2xl">
          <DialogHeader>
            <DialogTitle className="flex items-center gap-3 text-2xl">
              <Send className="h-6 w-6 text-teal-600" />
              Déposer une offre
            </DialogTitle>
            <p className="text-gray-600">
              Projet : <strong>{selectedProject?.title}</strong>
            </p>
          </DialogHeader>

          <form onSubmit={handleSubmitProposal} className="space-y-6 pt-4">
            <div>
              <Label htmlFor="price" className="text-sm font-medium text-gray-700 flex items-center gap-2">
                <Euro className="h-4 w-4 text-teal-600" />
                Prix proposé (€) *
              </Label>
              <Input
                id="price"
                type="number"
                step="0.01"
                value={newProposal.price}
                onChange={(e) => setNewProposal(prev => ({ ...prev, price: e.target.value }))}
                placeholder="Ex: 250.00"
                className="mt-2 h-12 rounded-lg border-gray-200 focus:border-teal-500 focus:ring-teal-500"
                required
              />
            </div>

            <div>
              <Label htmlFor="deliveryTime" className="text-sm font-medium text-gray-700 flex items-center gap-2">
                <Clock className="h-4 w-4 text-teal-600" />
                Délai de livraison
              </Label>
              <Input
                id="deliveryTime"
                value={newProposal.deliveryTime}
                onChange={(e) => setNewProposal(prev => ({ ...prev, deliveryTime: e.target.value }))}
                placeholder="Ex: 2 semaines, 10 jours..."
                className="mt-2 h-12 rounded-lg border-gray-200 focus:border-teal-500 focus:ring-teal-500"
              />
            </div>

            <div>
              <Label htmlFor="message" className="text-sm font-medium text-gray-700 flex items-center gap-2">
                <MessageSquare className="h-4 w-4 text-teal-600" />
                Message pour le client *
              </Label>
              <Textarea
                id="message"
                value={newProposal.message}
                onChange={(e) => setNewProposal(prev => ({ ...prev, message: e.target.value }))}
                placeholder="Présentez-vous, expliquez votre approche, votre expérience dans ce domaine..."
                rows={6}
                className="mt-2 rounded-lg border-gray-200 focus:border-teal-500 focus:ring-teal-500 resize-none"
                required
              />
            </div>

            <div className="flex gap-3 pt-4">
              <Button
                type="button"
                variant="outline"
                onClick={() => setProposalModalOpen(false)}
                className="flex-1"
                disabled={submittingProposal}
              >
                Annuler
              </Button>
              <Button
                type="submit"
                className="flex-1 bg-teal-600 hover:bg-teal-700"
                disabled={submittingProposal}
              >
                {submittingProposal ? (
                  <div className="flex items-center gap-2">
                    <div className="animate-spin rounded-full h-4 w-4 border-b-2 border-white"></div>
                    Envoi en cours...
                  </div>
                ) : (
                  <>
                    <Send className="h-4 w-4 mr-2" />
                    Envoyer l'offre
                  </>
                )}
              </Button>
            </div>
          </form>
        </DialogContent>
      </Dialog>
    </div>
  )
}

import {prisma} from "@/lib/prisma";
import Image from "next/image";
import Link from "next/link";

interface TailorPageProps {
  searchParams: {
    services?: string
    experience?: string
    type?: string
    city?: string
    search?: string
  }
}

export default async function TailorListPage({ searchParams }: TailorPageProps) {
  // Construire les filtres dynamiquement
  const where: any = {}

  if (searchParams.services) {
    where.servicesOffered = {
      contains: searchParams.services,
      mode: 'insensitive'
    }
  }

  if (searchParams.experience) {
    // Logique pour filtrer par années d'expérience
    const expRange = searchParams.experience
    if (expRange === '1-3') {
      where.yearsOfExperience = { gte: '1', lte: '3' }
    } else if (expRange === '3-5') {
      where.yearsOfExperience = { gte: '3', lte: '5' }
    } else if (expRange === '5-10') {
      where.yearsOfExperience = { gte: '5', lte: '10' }
    } else if (expRange === '10+') {
      where.yearsOfExperience = { gte: '10' }
    }
  }

  if (searchParams.type) {
    // Filtrer par type (individual vs professional)
    if (searchParams.type === 'individual') {
      where.companyType = null
    } else if (searchParams.type === 'professional') {
      where.companyType = { not: null }
    }
  }

  if (searchParams.city) {
    where.OR = [
      {
        companyCity: {
          contains: searchParams.city,
          mode: 'insensitive'
        }
      },
      {
        user: {
          address: {
            contains: searchParams.city,
            mode: 'insensitive'
          }
        }
      }
    ]
  }

  if (searchParams.search) {
    const searchOr = [
      {
        business_name: {
          contains: searchParams.search,
          mode: 'insensitive'
        }
      },
      {
        user: {
          firstname: {
            contains: searchParams.search,
            mode: 'insensitive'
          }
        }
      },
      {
        user: {
          lastname: {
            contains: searchParams.search,
            mode: 'insensitive'
          }
        }
      }
    ]

    if (where.OR) {
      where.AND = [
        { OR: where.OR },
        { OR: searchOr }
      ]
      delete where.OR
    } else {
      where.OR = searchOr
    }
  }

  const sellers = await prisma.seller.findMany({
    where,
    include: {
      user: true,
    },
    orderBy: { business_name: "asc" },
  });

  // Afficher les filtres actifs
  const activeFilters = Object.entries(searchParams).filter(([key, value]) =>
    value && ['services', 'experience', 'type', 'city'].includes(key)
  )

  return (
    <div className="container mx-auto px-4 py-8">
      <h1 className="text-2xl font-bold mb-6 text-center">Tous les Tailleurs</h1>

      {/* Affichage des filtres actifs */}
      {activeFilters.length > 0 && (
        <div className="mb-6">
          <div className="flex flex-wrap gap-2 items-center">
            <span className="text-sm text-gray-600">Filtres actifs:</span>
            {activeFilters.map(([key, value]) => (
              <div key={key} className="px-3 py-1 bg-teal-100 text-teal-800 rounded-full text-sm">
                {key === 'services' && value === 'alterations' && 'Services: Retouches'}
                {key === 'services' && value === 'custom' && 'Services: Confection sur mesure'}
                {key === 'services' && value === 'repairs' && 'Services: Réparations'}
                {key === 'services' && value === 'all' && 'Services: Tous services'}
                {key === 'experience' && `Expérience: ${value} ans`}
                {key === 'type' && value === 'individual' && 'Type: Particulier'}
                {key === 'type' && value === 'professional' && 'Type: Professionnel'}
                {key === 'city' && `Ville: ${value}`}
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Compteur de résultats */}
      <div className="mb-4">
        <p className="text-gray-600">
          {sellers.length} tailleur{sellers.length !== 1 ? 's' : ''} trouvé{sellers.length !== 1 ? 's' : ''}
        </p>
      </div>

      {/* Grille des tailleurs */}
      {sellers.length > 0 ? (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-5 gap-6">
          {sellers.map((seller) => (
            <Link
              key={seller.id}
              href={`/tailor/${seller.id}`}
              className="group relative block rounded-lg transition-transform hover:scale-105"
            >
              <div className="relative aspect-square overflow-hidden rounded-lg bg-gray-100 flex items-center justify-center">
                <Image
                  src={seller.user.image || "/placeholder-user.jpg"}
                  alt={seller.business_name}
                  width={200}
                  height={200}
                  className="object-cover w-full h-full rounded-lg"
                />
              </div>
              <div className="mt-2">
                <h3 className="text-sm font-medium">{seller.business_name}</h3>
                <p className="text-xs text-gray-600">{seller.user.firstname} {seller.user.lastname}</p>
                {/* Afficher les informations pertinentes */}
                <div className="text-xs text-gray-500 mt-1">
                  {seller.servicesOffered && (
                    <span className="block">Services: {
                      seller.servicesOffered === 'alterations' ? 'Retouches' :
                      seller.servicesOffered === 'custom' ? 'Sur mesure' :
                      seller.servicesOffered === 'repairs' ? 'Réparations' :
                      seller.servicesOffered === 'all' ? 'Tous services' :
                      seller.servicesOffered
                    }</span>
                  )}
                  {seller.yearsOfExperience && (
                    <span className="block">{seller.yearsOfExperience} ans d'expérience</span>
                  )}
                  {(seller.companyCity || seller.user.address) && (
                    <span className="block"> {seller.companyCity || seller.user.address}</span>
                  )}
                  {seller.companyType ? (
                    <span className="inline-block px-2 py-1 bg-blue-100 text-blue-800 rounded text-xs mt-1">
                      Professionnel
                    </span>
                  ) : (
                    <span className="inline-block px-2 py-1 bg-green-100 text-green-800 rounded text-xs mt-1">
                      Particulier
                    </span>
                  )}
                </div>
              </div>
            </Link>
          ))}
        </div>
      ) : (
        <div className="text-center py-12">
          <p className="text-gray-500 text-lg">Aucun tailleur trouvé avec ces filtres.</p>
          <p className="text-gray-400 text-sm mt-2">Essayez de modifier ou supprimer certains filtres.</p>
        </div>
      )}
    </div>
  );
}

